<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PANDATEC local layout review</title><style>body{font:15px Arial;margin:16px;background:#e8edf3;color:#14284b}header{padding:12px;background:white;margin-bottom:12px}button,select{padding:9px;margin:4px}iframe{display:block;border:1px solid #94a3b8;background:white;height:850px}#stage{overflow:auto}#result{padding:8px;background:white;white-space:pre-wrap}h1{font-size:20px}</style>
<header><h1>Local responsive layout review</h1><p>Same-origin iframe viewport testing. This is not a physical phone or a throttled performance test.</p><label>Page <select id="page"><option value="/">Homepage</option><option value="/products/machinery-automation/">Machinery</option><option value="/request-a-quote/">Enquiry form</option></select></label><label>Width <select id="width"><option>320</option><option selected>390</option><option>768</option><option>1440</option><option>1920</option></select></label><button id="apply">Show viewport</button><button id="inspect">Check layout</button><a href="/review/">Review notes</a></header><pre id="result" role="status">Loading…</pre><div id="stage"><iframe id="preview" title="Responsive PANDATEC preview" style="width:390px" src="/"></iframe></div>
<script>
const frame=document.querySelector('#preview'),result=document.querySelector('#result');
function inspect(){const d=frame.contentDocument,w=frame.contentWindow;const wide=[...d.querySelectorAll('main *,header,footer,dialog[open] *')].filter(e=>{const r=e.getBoundingClientRect(),s=w.getComputedStyle(e);return r.width&&s.visibility!=='hidden'&&s.display!=='none'&&(r.right>d.documentElement.clientWidth+1||r.left< -1)}).slice(0,8).map(e=>e.tagName+'.'+e.className);const grid=d.querySelector('.category-grid');result.textContent=JSON.stringify({page:w.location.pathname,width:w.innerWidth,documentWidth:d.documentElement.scrollWidth,horizontalOverflow:d.documentElement.scrollWidth>d.documentElement.clientWidth,visibleWideElements:wide,categoryColumns:grid?w.getComputedStyle(grid).gridTemplateColumns:null,missingImages:[...d.images].filter(i=>i.complete&&!i.naturalWidth).length},null,2);}
frame.addEventListener('load',inspect);document.querySelector('#inspect').onclick=inspect;document.querySelector('#apply').onclick=()=>{frame.style.width=document.querySelector('#width').value+'px';const url=document.querySelector('#page').value;if(frame.contentWindow.location.pathname!==url)frame.src=url;else inspect();};
</script></html>
